from enum import Enum
import platform as _platform

# 引用统一配置
from ahclaude_plugin.config.api_config import BACKEND_API


class AHReportType(str, Enum):
    LOG = 'LOG'
    ALERT = 'ALERT'
    ADOPTION = 'ADOPTION'
    VALID_CODE = 'VALID_CODE'
    INVALID_CODE = 'INVALID_CODE'
    GIT_USER_INFO = 'GIT_USER_INFO'
    APP_LOG = 'APP_LOG'
    COMMIT_DIFF_INFO = 'COMMIT_DIFF_INFO'
    COMMIT_TOTAL_INFO = 'COMMIT_TOTAL_INFO'
    MODEL_CONFIG = 'MODEL_CONFIG'
    MODEL_ACCESSIBILITY = 'MODEL_ACCESSIBILITY'
    MODEL_RECORD = 'MODEL_RECORD'

    def base_url(self) -> str:
        if self in (
            AHReportType.LOG, AHReportType.ALERT, AHReportType.ADOPTION,
            AHReportType.INVALID_CODE, AHReportType.GIT_USER_INFO,
            AHReportType.COMMIT_DIFF_INFO, AHReportType.COMMIT_TOTAL_INFO,
            AHReportType.MODEL_CONFIG, AHReportType.MODEL_ACCESSIBILITY,
            AHReportType.MODEL_RECORD,
        ):
            return BACKEND_API
        if self == AHReportType.VALID_CODE:
            return 'https://media.autohome.com.cn'
        if self == AHReportType.APP_LOG:
            return 'https://code.corpautohome.com'
        raise ValueError(f'Unknown report type: {self}')

    def endpoint(self) -> str:
        mapping = {
            AHReportType.LOG: '/log',
            AHReportType.ALERT: '/proxy/api/ide/alert/add',
            AHReportType.ADOPTION: '/proxy/api/ide/auto_code_add',
            AHReportType.VALID_CODE: '/proxy/api/ide/code',
            AHReportType.INVALID_CODE: '/proxy/api/ide/copy_record/add',
            AHReportType.GIT_USER_INFO: '/proxy/api/ide/gituserinfo',
            AHReportType.APP_LOG: '/api/automindlog/collect',
            AHReportType.COMMIT_DIFF_INFO: '/proxy/api/ide/no_permission/diff/add',
            AHReportType.COMMIT_TOTAL_INFO: '/proxy/api/ide/no_permission/total/add',
            AHReportType.MODEL_CONFIG: '/model/config',
            AHReportType.MODEL_ACCESSIBILITY: '/model/accessibility',
            AHReportType.MODEL_RECORD: '/model/record',
        }
        if self not in mapping:
            raise ValueError(f'Unknown report type: {self}')
        return mapping[self]


class AHHTTPMethod(str, Enum):
    GET = 'GET'
    POST = 'POST'
    PUT = 'PUT'
    DELETE = 'DELETE'


class AHReportError(Exception):
    def __init__(self, message: str, error_type: str):
        super().__init__(message)
        self.error_type = error_type

    @classmethod
    def invalid_request(cls, message: str) -> 'AHReportError':
        return cls(f'Invalid request: {message}', 'invalidRequest')

    @classmethod
    def network_failure(cls, error: Exception) -> 'AHReportError':
        return cls(f'Network failure: {error}', 'networkFailure')

    @classmethod
    def invalid_response(cls, message: str) -> 'AHReportError':
        return cls(f'Invalid response: {message}', 'invalidResponse')

    @classmethod
    def validation_failed(cls, message: str) -> 'AHReportError':
        return cls(f'Validation failed: {message}', 'validationFailed')

    @classmethod
    def configuration_missing(cls, message: str) -> 'AHReportError':
        return cls(f'Configuration missing: {message}', 'configurationMissing')

    @classmethod
    def unsupported_result_type(cls, message: str) -> 'AHReportError':
        return cls(f'Unsupported result type: {message}', 'unsupportedResultType')
